alter table public.friendships enable row level security;
alter table public.posts enable row level security;

create function public.is_friend_of(target_user_id uuid)
returns boolean
language sql
security definer
as $$
  select exists (
    select 1 from public.friendships f
    where (f.requester_id = auth.uid() and f.addressee_id = target_user_id)
       or (f.requester_id = target_user_id and f.addressee_id = auth.uid())
    and f.status = 'accepted'
  );
$$;

create policy "Users can read public posts"
on public.posts
for select
to anon, authenticated
using (audience = 'public');

create policy "Users can read friends' posts"
on public.posts
for select
to authenticated
using (
  audience = 'friends'
  and public.is_friend_of(author_id)
);

create policy "Users can read own posts"
on public.posts
for select
to authenticated
using (author_id = auth.uid());

create policy "Users can insert own posts"
on public.posts
for insert
to authenticated
with check (author_id = auth.uid());

create policy "Users can update own posts"
on public.posts
for update
to authenticated
using (author_id = auth.uid())
with check (author_id = auth.uid());

create policy "Users can delete own posts"
on public.posts
for delete
to authenticated
using (author_id = auth.uid());

create policy "Users can send friend requests"
on public.friendships
for insert
to authenticated
with check (
  requester_id = auth.uid()
  and status = 'pending'
  and requester_id <> addressee_id
);

create policy "Addressees can accept pending requests"
on public.friendships
for update
to authenticated
using (
  addressee_id = auth.uid()
  and status = 'pending'
)
with check (
  addressee_id = auth.uid()
  and status = 'accepted'
);

create policy "Users can delete friendships they are part of"
on public.friendships
for delete
to authenticated
using (
  requester_id = auth.uid()
  or addressee_id = auth.uid()
);

create policy "Users can read friendships they are part of"
on public.friendships
for select
to authenticated
using (
  requester_id = auth.uid()
  or addressee_id = auth.uid()
);

grant usage on schema public to anon, authenticated;
grant select on public.posts to anon, authenticated;
grant select, insert, update, delete on public.posts to authenticated;
grant select, insert, update, delete on public.friendships to authenticated;
