create function public.is_sso_session()
returns boolean
language sql
security definer
as $$
  select exists (
    select 1 from jsonb_array_elements_text(auth.jwt() -> 'amr') as method
    where method = 'sso/saml'
  );
$$;

create function public.is_org_admin(p_org_id bigint)
returns boolean
language sql
security definer
as $$
  select exists (
    select 1 from public.org_members om
    where om.org_id = p_org_id
      and om.user_id = auth.uid()
      and om.role = 'admin'
  );
$$;

create function public.is_org_member(p_org_id bigint)
returns boolean
language sql
security definer
as $$
  select exists (
    select 1 from public.org_members om
    where om.org_id = p_org_id
      and om.user_id = auth.uid()
  );
$$;

create policy "R1: Members can see their organizations"
on public.orgs
for select
to authenticated
using (
  public.is_org_member(id)
  and (
    public.is_sso_session() = false
    or require_sso = false
  )
);

create policy "R1: Members can see organization members"
on public.org_members
for select
to authenticated
using (
  public.is_org_member(org_id)
  and (
    public.is_sso_session() = false
    or require_sso = false
  )
);

create policy "R1: Members can see organization documents"
on public.org_documents
for select
to authenticated
using (
  public.is_org_member(org_id)
  and (
    public.is_sso_session() = false
    or require_sso = false
  )
);

create policy "R2: Admins can create documents"
on public.org_documents
for insert
to authenticated
with check (
  public.is_org_admin(org_id)
  and public.is_sso_session()
);

create policy "R2: Admins can update documents"
on public.org_documents
for update
to authenticated
using (
  public.is_org_admin(org_id)
  and public.is_sso_session()
)
with check (
  public.is_org_admin(org_id)
  and public.is_sso_session()
);

create policy "R2: Admins can delete documents"
on public.org_documents
for delete
to authenticated
using (
  public.is_org_admin(org_id)
  and public.is_sso_session()
);

create policy "R3: Admins can update organization settings"
on public.orgs
for update
to authenticated
using (
  public.is_org_admin(id)
  and public.is_sso_session()
)
with check (
  public.is_org_admin(id)
  and public.is_sso_session()
);

create policy "R3: Admins can delete organization settings"
on public.orgs
for delete
to authenticated
using (
  public.is_org_admin(id)
  and public.is_sso_session()
);

create policy "R4: No membership changes allowed"
on public.org_members
for all
to authenticated
using (false)
with check (false);

grant usage on schema public to anon, authenticated;
grant select on public.orgs to authenticated;
grant select on public.org_members to authenticated;
grant select on public.org_documents to authenticated;
grant insert, update, delete on public.org_documents to authenticated;
grant update, delete on public.orgs to authenticated;
revoke all on public.org_members from anon;
revoke all on public.orgs from anon;
revoke all on public.org_documents from anon;
