```sql
alter table public.units enable row level security;
alter table public.residents enable row level security;
alter table public.building_staff enable row level security;
alter table public.requests enable row level security;
alter table public.request_photos enable row level security;

create function public.is_resident_of_unit(p_unit_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.residents r
    where r.unit_id = p_unit_id and r.user_id = auth.uid()
  );
$$ language sql security definer;

create function public.is_building_staff(p_building_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.building_staff s
    where s.building_id = p_building_id and s.user_id = auth.uid()
  );
$$ language sql security definer;

create function public.get_building_id_from_unit(p_unit_id bigint)
returns bigint as $$
  select building_id from public.units where id = p_unit_id;
$$ language sql security definer;

create function public.get_building_id_from_resident()
returns bigint as $$
  select u.building_id from public.units u
  join public.residents r on r.unit_id = u.id
  where r.user_id = auth.uid();
$$ language sql security definer;

create function public.get_building_id_from_staff()
returns bigint as $$
  select building_id from public.building_staff where user_id = auth.uid();
$$ language sql security definer;

create function public.get_building_id_from_request(p_request_id bigint)
returns bigint as $$
  select u.building_id from public.units u
  join public.requests r on r.unit_id = u.id
  where r.id = p_request_id;
$$ language sql security definer;

create policy "Residents can view their own units"
on public.units for select
to authenticated
using (public.is_resident_of_unit(id));

create policy "Building staff can view units in their buildings"
on public.units for select
to authenticated
using (public.is_building_staff(building_id));

create policy "Residents can view their own residents"
on public.residents for select
to authenticated
using (user_id = auth.uid());

create policy "Building staff can view their own staff"
on public.building_staff for select
to authenticated
using (user_id = auth.uid());

create policy "Residents can create requests for their own units"
on public.requests for insert
to authenticated
with check (
  public.is_resident_of_unit(unit_id)
  and created_by = auth.uid()
  and status = 'open'
);

create policy "Residents can view their own requests"
on public.requests for select
to authenticated
using (public.is_resident_of_unit(unit_id));

create policy "Building staff can view requests in their buildings"
on public.requests for select
to authenticated
using (public.is_building_staff(public.get_building_id_from_request(id)));

create policy "Residents and staff can add photos to visible requests"
on public.request_photos for insert
to authenticated
with check (
  exists (
    select 1 from public.requests r
    where r.id = request_id
    and (
      public.is_resident_of_unit(r.unit_id)
      or public.is_building_staff(public.get_building_id_from_request(r.id))
    )
  )
);

create policy "Residents can view photos of their own units"
on public.request_photos for select
to authenticated
using (
  exists (
    select 1 from public.requests r
    where r.id = request_id
    and public.is_resident_of_unit(r.unit_id)
  )
);

create policy "Building staff can view photos in their buildings"
on public.request_photos for select
to authenticated
using (
  exists (
    select 1 from public.requests r
    where r.id = request_id
    and public.is_building_staff(public.get_building_id_from_request(r.id))
  )
);

create policy "Building staff can update request status in their buildings"
on public.requests for update
to authenticated
using (
  public.is_building_staff(public.get_building_id_from_request(id))
  and status in ('open', 'in_progress', 'done')
)
with check (
  public.is_building_staff(public.get_building_id_from_request(id))
  and status in ('open', 'in_progress', 'done')
);

create policy "Prevent deletion of requests"
on public.requests for delete
to authenticated
using (false);

create policy "Prevent updates to request fields other than status"
on public.requests for update
to authenticated
using (
  public.is_building_staff(public.get_building_id_from_request(id))
  and (
    (created_by = auth.uid() and status = 'open')
    or (status != 'open' and created_by != auth.uid())
  )
)
with check (
  public.is_building_staff(public.get_building_id_from_request(id))
  and (
    (created_by = auth.uid() and status = 'open')
    or (status != 'open' and created_by != auth.uid())
  )
);

create policy "Prevent updates to units"
on public.units for update
to authenticated
using (false);

create policy "Prevent updates to residents"
on public.residents for update
to authenticated
using (false);

create policy "Prevent updates to building_staff"
on public.building_staff for update
to authenticated
using (false);

create policy "Prevent updates to request_photos"
on public.request_photos for update
to authenticated
using (false);

create policy "Prevent deletion of units"
on public.units for delete
to authenticated
using (false);

create policy "Prevent deletion of residents"
on public.residents for delete
to authenticated
using (false);

create policy "Prevent deletion of building_staff"
on public.building_staff for delete
to authenticated
using (false);

create policy "Prevent deletion of request_photos"
on public.request_photos for delete
to authenticated
using (false);

