$$ language sql security definer;

create function public.get_resident_unit_ids()
returns bigint[] as $$
  select array_agg(unit_id) from public.residents where user_id = auth.uid();
$$ language sql security definer;

create function public.get_staff_building_ids()
returns bigint[] as $$
  select array_agg(building_id) from public.building_staff where user_id = auth.uid();
$$ language sql security definer;

create policy "units_select_residents_own" on public.units
  for select
  to authenticated
  using (
