create function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer
as $$
declare
  v_auction record;
  v_highest_bid numeric;
  v_min_increment numeric;
  v_starting_price numeric;
  v_seller_id uuid;
  v_bidder_id uuid;
  v_ends_at timestamptz;
begin
  if auth.uid() is null then
    raise exception 'User must be signed in to place a bid';
  end if;

  select * into v_auction
  from public.auctions
  where id = p_auction_id;

  if v_auction is null then
    raise exception 'Auction does not exist';
  end if;

  if v_auction.ends_at <= now() then
    raise exception 'Auction has ended';
  end if;

  if v_auction.seller_id = auth.uid() then
    raise exception 'Sellers cannot place bids on their own auctions';
  end if;

  v_bidder_id := auth.uid();
  v_highest_bid := v_auction.highest_bid;
  v_min_increment := v_auction.min_increment;
  v_starting_price := v_auction.starting_price;

  if v_highest_bid is null then
    if p_amount < v_starting_price then
      raise exception 'Bid amount must be at least the starting price';
    end if;
  else
    if p_amount <= v_highest_bid + v_min_increment then
      raise exception 'Bid amount must be higher than the current highest bid plus the minimum increment';
    end if;
  end if;

  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, v_bidder_id, p_amount, now());

  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = v_bidder_id
  where id = p_auction_id;

  return p_amount;
end;
$$;

