create function public.is_instructor_of_class(p_class_id bigint)
returns boolean
language sql
security definer
as $$
  select exists (
    select 1 from public.classes c
    where c.id = p_class_id
    and c.instructor_id = auth.uid()
  );
$$;

create function public.get_enrolled_count(p_class_id bigint)
returns integer
language sql
security definer
as $$
  select count(*) from public.class_spots
  where class_id = p_class_id
  and status = 'enrolled';
$$;

create policy "classes_select_all_authenticated"
on public.classes
for select
to authenticated
using (true);

create policy "class_spots_select_members_own"
on public.class_spots
for select
to authenticated
using (
  user_id = auth.uid()
  or public.is_instructor_of_class(class_id)
);

create policy "class_spots_insert_members_join"
on public.class_spots
for insert
to authenticated
with check (
  user_id = auth.uid()
  and status in ('enrolled', 'waitlisted')
  and (
    status = 'enrolled'
    and (select capacity from public.classes where id = class_id) > (select count(*) from public.class_spots where class_id = class_id and status = 'enrolled')
  )
);

create policy "class_spots_update_waitlist_to_enroll"
on public.class_spots
for update
to authenticated
using (
  user_id = auth.uid()
  and status = 'waitlisted'
  and (select capacity from public.classes where id = class_id) > (select count(*) from public.class_spots where class_id = class_id and status = 'enrolled')
)
with check (
  user_id = auth.uid()
  and status = 'enrolled'
);

create policy "class_spots_delete_own"
on public.class_spots
for delete
to authenticated
using (
  user_id = auth.uid()
);

create policy "class_spots_delete_instructor"
on public.class_spots
for delete
to authenticated
using (
  public.is_instructor_of_class(class_id)
);

create policy "classes_update_nothing"
on public.classes
for update
to authenticated
using (false)
with check (false);

create policy "classes_insert_nothing"
on public.classes
for insert
to authenticated
with check (false);

